cmplsTeP2mpTunnelDestEntry = MibTableRow((1, 3, 6, 1, 4, 1, 9, 10, 142, 2, 3, 1), ).setMaxAccess("notaccessible").setIndexNames((0, "MPLS-TE-STD-MIB", "mplsTunnelIndex"), (0, "MPLS-TE-STD-MIB", "mplsTunnelInstance"), (0, "MPLS-TE-STD-MIB", "mplsTunnelIngressLSRId"), (0, "MPLS-TE-STD-MIB", "mplsTunnelEgressLSRId"), (0, "CISCO-IETF-MPLS-TE-P2MP-STD-MIB", "cmplsTeP2mpTunnelDestSrcSubGroupOriginType"), (0, "CISCO-IETF-MPLS-TE-P2MP-STD-MIB", "cmplsTeP2mpTunnelDestSrcSubGroupOrigin"), (0, "CISCO-IETF-MPLS-TE-P2MP-STD-MIB", "cmplsTeP2mpTunnelDestSrcSubGroupID"), (0, "CISCO-IETF-MPLS-TE-P2MP-STD-MIB", "cmplsTeP2mpTunnelDestSubGroupOriginType"), (0, "CISCO-IETF-MPLS-TE-P2MP-STD-MIB", "cmplsTeP2mpTunnelDestSubGroupOrigin"), (0, "CISCO-IETF-MPLS-TE-P2MP-STD-MIB", "cmplsTeP2mpTunnelDestSubGroupID"), (0, "CISCO-IETF-MPLS-TE-P2MP-STD-MIB", "cmplsTeP2mpTunnelDestDestinationType"), (0, "CISCO-IETF-MPLS-TE-P2MP-STD-MIB", "cmplsTeP2mpTunnelDestDestination"))
